var app = new Vue({
  el: "#app",
  delimiters: ["[[", "]]"],
  data: {
    loading: [],
    FB: {},
    model: {},
    scope: {},
    lgoptions: {
      scope:
        "email, public_profile, pages_read_user_content, pages_show_list, pages_manage_metadata, pages_manage_engagement, pages_messaging, pages_read_engagement",
    },
    listPages: [],
  },
  methods: {
    handleSdkInit({ FB, scope }) {
      this.FB = FB;
      this.scope = scope;
    },
    getListPage() {
      if (this.model.connected) {
        this.loading.push("Loading");
        const path = window.location.origin + "/dashboard/settings";
        axios
          .post(path)
          .then((response) => {
            this.loading.splice(0, 1);
            this.listPages = response.data;
          })
          .catch((error) => {
            console.log(error);
          });
      } else {
          this.scope.login();
      }
    },
    sendPageUID(index) {
      this.loading.push("Loading");
      const path =
        window.location.origin +
        "/dashboard/settings/" +
        this.listPages[index].uid;
      axios
        .put(path)
        .then((response) => {
          this.loading.splice(0, 1);
          this.listPages = response.data;
        })
        .catch((error) => {
          console.log(error);
        });
    },
    handleLogin() {
      this.FB.getLoginStatus(function (response) {
        if (response.status === "connected") {
          const uid = response.authResponse.userID;
          const accessToken = response.authResponse.accessToken;
          const path = window.location.origin + "/dashboard/settings/status";
          axios
            .post(path, {
              token: accessToken,
              uid: uid,
            })
            .catch((error) => {
              console.log(error);
            });
        }
      });
    },
    getData() {
      const path = window.location.origin + "/dashboard/settings/data";
      axios
        .get(path)
        .then((response) => {
          this.listPages = response.data;
        })
        .catch((error) => {
          console.log(error);
        });
    },
    deletePage() {
      this.loading.push("Loading");
      const path = window.location.origin + "/dashboard/settings";
      axios
        .delete(path)
        .then((response) => {
          this.loading.splice(0, 1);
          this.listPages = response.data;
        })
        .catch((error) => {
          console.log(error);
        });
    },
  },
  created() {
    this.getData();
  },
});
